QUERY_TEXT:
/* cppi::30724e3a6efeb6e10e84adaf2acd99dfae0568c93a5104c67e2d0ee1c6c3cba0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-12' and end_date = '2025-05-12')
and start_date = '2025-05-12' and end_date = '2025-05-12'

/* cppi::af3cad3300d08cae43086da5ba9384c575426e140bedaea73c7d6c3e78552c5f */
SELECT * FROM ci_etl_db_dev.dealcloud_deal_fundings_schedule_extract
WHERE date = REPLACE('2025-06-19', '-', '')

/* cppi::b26dd87021709c56463415f3f5ae4b8621a3d0f337405582d6c9fa380e90908b */
SELECT cppib_sec_id, rating_value FROM performance.cppib_security_rating
                WHERE business_date = '2025-05-01' AND rating_agency = 'CPPIB'

/* cppi::744223ae33cbf375f0c7a4be17238ad3dd9bd211f0c0c0b2ae23aa7fdee72fec */
SELECT business_date FROM trades_deals.scd_transactions_entity
WHERE accounting_framework_id <> 'PCLFWKENT'

/* cppi::0e512201d96b7e4a2ff2b40f7ab49640b6d61698276c08aee6885a573506d3f4 */
SELECT * FROM trades_deals.scd_transactions
WHERE accounting_framework_id <> 'PCLFWKMAIN'

/* cppi::3c1cfcfb06507d3cdd9d2b685c3eaf0267c07a4470ff6c0e3172f8c02bc269b8 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-01' and end_date = '2025-04-01')
and start_date = '2025-04-01' and end_date = '2025-04-01'

/* cppi::5fa058b16e07f42e451b88fdc4dc2d3b1736ae8d26eda92ab577fe658616b0e0 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-09' and business_date <= date '2025-06-23' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::00750506d14ff9fbd1264db392a9aee716f74a403fa0cb717eef8dcb565ce771 */
select date_, security_id, bmi_country_code, gics_code from asset.qsrp_security_identifiers
                     where date_ between date '2005-01-01' and date '2005-12-31'

/* cppi::213b19b2d8f94d089c7bed67e9ded3680f5a5aaf8e487f101c5c4698189b9363 */
select dataset_id,business_date,time_weighted_return_fiscal_year_to_date_reporting_currency
from performance.scd_performance_bottom_up 
where dataset_id='TOTALFUND'
and business_date='2025-06-16' limit 500 -- {"user": "aluc@cppib.com", "source": "pyxll"}

/* cppi::db02eda4b6739916560acc0d81ceb8318fa78c39098f2491968a1507dd49243a */
select max(business_date) from performance.scd_performance_bottom_up
LIMIT 200

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::db6c21e9dc1d7782ac6df6d5edbeb60be72910588d026fb02c07dd8bb7da3ef1 */
SELECT cppib_party_id, rating_value FROM performance.cppib_party_rating
                WHERE business_date = '2025-05-01' AND rating_agency = 'CPPIB'

