/* cppi::d0d0045abb6a21c32c795d1d10e97f7b513be945294e17e8e72744c1e000d2dd */
select date_, security_id, bmi_country_code, gics_code from asset.qsrp_security_identifiers
                     where date_ between date '2006-01-01' and date '2006-12-31'

/* cppi::34b4152c78d5f0d59250a218d00c026b9ec561f35909d56333b07b0711e38b8f */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-19' and business_date <= date '2025-06-23' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::6bf12150167ac47d096f1ea31def984bd6cf76e7f3e090ed283554a08a12fce6 */
select * from tfm_qa.ioa_atp_weights
where business_date = '2025-04-04' -- '2025-01-23'

/* cppi::308541259928ab3c2b5547891c62ba5a09fa8d7aea363b006e1b969069a4c23e */
/* QuickSight 0d3ee5db-033b-4fd5-9f96-a9e03e3f3898 */
